local function log(s)
  print(s)
  if io and io.open then
    local f = io.open(logPath, 'a')
    if f then f:write(s .. '\n') f:close() end
  end
end
local function check(v, what)
  if v == nil or v == false then error('FAILED: ' .. what) end
  return v
end
local function main()
  log('BEGIN ' .. os.date('!%Y-%m-%dT%H:%M:%SZ'))
  check(resolve, 'Resolve API unavailable')
  local pm = check(resolve:GetProjectManager(), 'project manager')
  local project = check(pm:GetCurrentProject(), 'no project open')
  local pname = project:GetName()
  log('PROJECT ' .. pname .. ' product=' .. tostring(resolve:GetProductName()))
  if pname ~= plan.project then
    error('ACTIVE PROJECT IS "' .. pname .. '" BUT EXPECTED "' .. plan.project .. '"')
  end
  local pool = check(project:GetMediaPool(), 'media pool')
  local rootFolder = check(pool:GetRootFolder(), 'root folder')
  local folder = pool:AddSubFolder(rootFolder, 'Day01-v2 Media')
  if folder then pool:SetCurrentFolder(folder) log('MEDIAFOLDER Day01-v2 Media') end
  local media = {}
  for _, m in ipairs(plan.media) do
    local files = pool:ImportMedia({m.path})
    if files == nil or files[1] == nil then error('IMPORT FAILED: ' .. m.path) end
    media[m.key] = files[1]
    log('IMPORT ok=' .. m.key .. ' path=' .. m.path)
  end
  local tl = check(pool:CreateEmptyTimeline(plan.timeline), 'create timeline')
  check(project:SetCurrentTimeline(tl), 'set current timeline')
  log('TIMELINE ' .. plan.timeline)
  -- Timeline-scoped format: the user's project-wide settings are left alone.
  check(tl:SetSettings({useCustomSettings='1',
        timelineResolutionWidth=tostring(plan.width),
        timelineResolutionHeight=tostring(plan.height),
        timelineFrameRate=tostring(plan.fps),
        timelinePixelAspectRatio='square'}), 'timeline settings')
  tl:SetStartTimecode('00:00:00:00')
  local tfps = tonumber(tostring(tl:GetSetting('timelineFrameRate')))
  if tfps == nil or math.abs(tfps - plan.fps) > 0.5 then
    log('WARN timeline fps read back as ' .. tostring(tl:GetSetting('timelineFrameRate')) .. '; applying project fallback')
    check(project:SetSettings({timelineFrameRate=tostring(plan.fps),
          timelinePlaybackFrameRate=tostring(plan.fps),
          timelineResolutionWidth=tostring(plan.width),
          timelineResolutionHeight=tostring(plan.height)}), 'project settings fallback')
  end
  log('TLSETTINGS w=' .. tostring(tl:GetSetting('timelineResolutionWidth'))
      .. ' h=' .. tostring(tl:GetSetting('timelineResolutionHeight'))
      .. ' fps=' .. tostring(tl:GetSetting('timelineFrameRate'))
      .. ' startFrame=' .. tostring(tl:GetStartFrame()))
  local needVideo, needAudio = 1, 1
  for _, t in ipairs(plan.tracks) do
    if t[1] == 'video' and t[2] > needVideo then needVideo = t[2] end
    if t[1] == 'audio' and t[2] > needAudio then needAudio = t[2] end
  end
  while tl:GetTrackCount('video') < needVideo do check(tl:AddTrack('video'), 'add video track') end
  while tl:GetTrackCount('audio') < needAudio do check(tl:AddTrack('audio'), 'add audio track') end
  for _, t in ipairs(plan.tracks) do
    check(tl:SetTrackName(t[1], t[2], t[3]), 'track name ' .. t[1] .. t[2])
    log('TRACK ' .. t[1] .. ':' .. t[2] .. ':' .. t[3])
  end
  for i, c in ipairs(plan.clips) do
    local entry = {mediaPoolItem=media[c.key], startFrame=c.startFrame, endFrame=c.endFrame,
                   recordFrame=c.recordFrame, trackIndex=c.track, mediaType=c.mediaType}
    local res = pool:AppendToTimeline({entry})
    if res == nil or res[1] == nil then error('APPEND FAILED clip ' .. i .. ' key=' .. c.key) end
    local item = res[1]
    if c.name and c.name ~= '' then item:SetName(c.name) end
    if c.speedPct and c.speedPct ~= 100 then
      if not item:SetSpeed({Percentage=c.speedPct}) then
        log('ERR setspeed idx=' .. i .. ' key=' .. c.key .. ' pct=' .. c.speedPct)
      else
        local sp = item:GetSpeed() or {}
        log('SPEED idx=' .. i .. ' key=' .. c.key .. ' pct=' .. c.speedPct
            .. ' reported=' .. tostring(sp['Percentage']))
      end
    end
    log('CLIP idx=' .. i .. ' key=' .. c.key .. ' track=' .. c.track
        .. ' rec=' .. c.recordFrame .. ' src=' .. c.startFrame .. '..' .. c.endFrame
        .. ' start=' .. tostring(item:GetStart()) .. ' end=' .. tostring(item:GetEnd())
        .. ' dur=' .. tostring(item:GetDuration()))
  end
  for _, m in ipairs(plan.markers) do
    check(tl:AddMarker(m.frame, 'Blue', m.name, m.note, 1), 'marker ' .. m.name)
    log('MARKER ' .. m.frame .. ':' .. m.name)
  end
  log('TRACKCOUNT video=' .. tl:GetTrackCount('video') .. ' audio=' .. tl:GetTrackCount('audio'))
  for kind, idx in pairs({['video']=1, ['audio']=1}) do
    local n = #tl:GetItemListInTrack(kind, idx)
    log('TRACKITEMS ' .. kind .. ':' .. idx .. '=' .. n)
  end
  local marks = tl:GetMarkers()
  local mc = 0
  for _ in pairs(marks) do mc = mc + 1 end
  log('MARKERCOUNT ' .. mc)
  log('SAVEPROJECT ' .. tostring(pm:SaveProject()))
  log('EXPORTDRP ' .. tostring(pm:ExportProject(project:GetName(), plan.drp)) .. ' ' .. plan.drp)
  log('DONE ' .. os.date('!%Y-%m-%dT%H:%M:%SZ'))
end
local ok, err = xpcall(main, function(e) return tostring(e) end)
if not ok then log('BLOCKED ' .. tostring(err)) end
log('BUILD_END_ZZ ' .. os.date('!%Y-%m-%dT%H:%M:%SZ'))

